# Remove duplicates and choose round-robin by sport to ensure wide coverage.
original=json.loads((P/'athletes_252.json').read_text())
orig_perks=json.loads((P/'signature_perks_252.json').read_text())
athletes=original['athletes'][:];perks=orig_perks['perks'][:]
slug=lambda s:re.sub(r'-+', '-', re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower())).strip('-')
existing={x['id'] for x in athletes};normalized={slug(x['display_name']) for x in athletes}
by_sport={sport:[] for sport in CANDIDATES}
for sport,string in CANDIDATES.items():
 for name in string.split('|'):
  name=name.strip();sid=slug(name)
  if not name or sid in normalized:continue
  normalized.add(sid);by_sport[sport].append(name)
chosen=[]
while len(chosen)<248:
 prev=len(chosen)
 for sport,names in by_sport.items():
  if names:
   chosen.append((sport,names.pop(0)))
   if len(chosen)==248:break
 if len(chosen)==prev:raise RuntimeError('Not enough unique named candidates')
for sport,name in chosen:
 id=slug(name)
 if id in existing:raise RuntimeError('Duplicate ID '+id)
 existing.add(id)
 role=rules.ROLE_BY_NAME.get(name,rules.DEFAULT_ROLES[sport]);ratings=dict(zip(rules.FIELDS,rules.BASE[sport]))
 for k,delta in rules.ROLES[role].items():ratings[k]+=delta
 ratings={f:rules.clamp(v+rules.deterministic_jitter(id,f)) for f,v in ratings.items()}
 perk_name,trigger,bonus,stat=rules.STYLE[role]
 perk_id='SIGNATURE_'+id.upper().replace('-','_')
 if perk_id in {p['id'] for p in perks}:raise RuntimeError('Duplicate perk '+perk_id)
 cost=3 if bonus<=7 else 6
 activation='once_per_encounter' if trigger in ('open_sprint','first_contact','contact_defense','contested_supply','urban_evasion','group_coordination','under_pressure') else 'once_per_match'
 behavior={k:max(0,min(100,round(v+rules.deterministic_jitter(id,k,7)))) for k,v in {'aggression':55,'caution':58,'alliance_drive':58,'loyalty':62,'opportunism':65}.items()}
 if role in ('quarterback','point_guard','soccer_midfielder'):behavior['alliance_drive']=min(95,behavior['alliance_drive']+14)
 if role in ('boxer','mma_grappler','mma_striker','combat_grappler'):behavior['aggression']=min(92,behavior['aggression']+12)
 a={'id':id,'display_name':name,'sport':sport,'sport_role':role,'appearance':{'edition_label':None,'outfit_type':{'Basketball':'basketball_jersey','American Football':'football_jersey','Association Football':'soccer_kit','Baseball':'baseball_uniform','Boxing & MMA':'boxing_trunks','Track & Field':'track_singlet','Swimming':'swimwear','Tennis':'tennis_uniform','Ice Hockey':'hockey_uniform','Gymnastics':'gymnastics_uniform'}.get(sport,'sport_kit'),'candidate_number':None,'display_number':None,'number_kind':None,'verification_status':'NEEDS_REVIEW','verification_sources':[]},'ratings':ratings,'fictional_behavior':behavior,'signature_perk':perk_id,'secondary_perks':rules.SECONDARY[role][:],'data_quality':{'ratings_are_provisional':True,'ratings_method':'sport_role_archetype_with_deterministic_variation','ratings_historical_verification':'NOT_VERIFIED','personality_is_fictional':True,'appearance_number_verified':False,'licensing_reviewed':False,'source_links':[]},'description':f'Fantasy game profile: {role.replace("_"," ")} archetype; attributes are estimates for play balancing, not measurements or claims about real-world behavior.'}
 p={'id':perk_id,'athlete_id':id,'name':f'{name.split()[-1]}: {perk_name}','trigger':trigger,'bonus':bonus,'target_stat':stat,'stamina_cost':cost,'activation_limit':activation,'source':'gameplay_design_provisional','description':f'Fictional sport-inspired ability: when {trigger.replace("_", " ")} applies, adds +{bonus} to a {stat}-based check; incurs {cost} stamina on activation.','validated_against_athlete_biography':False}
 athletes.append(a);perks.append(p)
assert len(athletes)==len(perks)==500
assert len({x['id'] for x in athletes})==500
assert len({x['id'] for x in perks})==500
assert all(len(x['ratings'])==20 for x in athletes)
(P/'athletes_500.json').write_text(json.dumps({'version':'0.3.0','count':500,'verification_notice':'Athlete names are curated but all new ratings and behavior are unvalidated fictional design estimates; numbers not displayed unless previously verified.','athletes':athletes},indent=2,ensure_ascii=False)+'\n')
(P/'signature_perks_500.json').write_text(json.dumps({'version':'0.3.0','count':500,'perks':perks},indent=2,ensure_ascii=False)+'\n')
with (P/'athletes_500_summary.csv').open('w',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=['id','name','sport','role','display_number','verified_number','signature_perk']+rules.FIELDS);w.writeheader()
 for a in athletes:w.writerow(dict(id=a['id'],name=a['display_name'],sport=a['sport'],role=a['sport_role'],display_number=a['appearance']['display_number'],verified_number=a['data_quality']['appearance_number_verified'],signature_perk=a['signature_perk'],**a['ratings']))
(P/'roster_expansion_review.json').write_text(json.dumps({'count':248,'profile_ids':[a['id'] for a in athletes[252:]],'review_required':['name_and_sport','ratings','perk','uniform','licensing'],'verified_numbers_new':0},indent=2)+'\n')
print('ROSTER',len(athletes),'NEW',len(chosen),'BY SPORT',__import__('collections').Counter(sport for sport,_ in chosen))
